import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Spaltentypen","description":"Alle Spaltentypen in ApptiveGrid mit Einstellungen, Formularverhalten und Filterbedingungen.","frontmatter":{"title":"Spaltentypen","description":"Alle Spaltentypen in ApptiveGrid mit Einstellungen, Formularverhalten und Filterbedingungen."},"headers":[],"relativePath":"referenz/spaltentypen.md","filePath":"referenz/spaltentypen.md","lastUpdated":1786434193000}'),a={name:"referenz/spaltentypen.md"};function l(s,e,d,o,u,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="spaltentypen-—-referenz" tabindex="-1">Spaltentypen — Referenz <a class="header-anchor" href="#spaltentypen-—-referenz" aria-label="Permalink to &quot;Spaltentypen — Referenz&quot;">​</a></h1><p>Jedes Feld eines Grids hat einen Spaltentyp. Er bestimmt die zulässigen Werte, die Darstellung, die verfügbaren Filterbedingungen und das Verhalten in Formularen.</p><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Spaltentyp</th><th>Kurzbeschreibung</th><th>In Formularen</th><th>Summierbar</th></tr></thead><tbody><tr><td><a href="#text">Text</a></td><td>Einzeiliger Text</td><td>✓</td><td>–</td></tr><tr><td><a href="#formatierter-text">Formatierter Text</a></td><td>Text mit Formatierung</td><td>–</td><td>–</td></tr><tr><td><a href="#zahl">Zahl</a></td><td>Ganze Zahl</td><td>✓</td><td>✓</td></tr><tr><td><a href="#kommazahl">Kommazahl</a></td><td>Zahl mit Nachkommastellen</td><td>✓</td><td>✓</td></tr><tr><td><a href="#waehrung">Währung</a></td><td>Geldbetrag mit Währung</td><td>✓</td><td>✓</td></tr><tr><td><a href="#datum">Datum</a></td><td>Datum ohne Uhrzeit</td><td>✓</td><td>–</td></tr><tr><td><a href="#datum-und-uhrzeit">Datum und Uhrzeit</a></td><td>Zeitpunkt</td><td>✓</td><td>–</td></tr><tr><td><a href="#haekchen">Häkchen</a></td><td>Ja/Nein</td><td>✓</td><td>–</td></tr><tr><td><a href="#einzelauswahl">Einzelauswahl</a></td><td>Eine Option aus einer Liste</td><td>✓</td><td>–</td></tr><tr><td><a href="#mehrfachauswahl">Mehrfachauswahl</a></td><td>Mehrere Optionen</td><td>✓</td><td>–</td></tr><tr><td><a href="#eintrag-verknuepfen">Eintrag verknüpfen</a></td><td>Verweis auf einen Eintrag</td><td>✓</td><td>–</td></tr><tr><td><a href="#mehrere-eintraege-verknuepfen">Mehrere Einträge verknüpfen</a></td><td>Verweise auf mehrere Einträge</td><td>✓</td><td>–</td></tr><tr><td><a href="#dateien">Dateien</a></td><td>Datei- und Bild-Anhänge</td><td>✓</td><td>–</td></tr><tr><td><a href="#adresse">Adresse</a></td><td>Postanschrift</td><td>✓</td><td>–</td></tr><tr><td><a href="#geolokalisierung">Geolokalisierung</a></td><td>Koordinaten</td><td>✓</td><td>–</td></tr><tr><td><a href="#e-mail">E-Mail</a></td><td>E-Mail-Adresse</td><td>✓</td><td>–</td></tr><tr><td><a href="#telefon">Telefon</a></td><td>Telefonnummer</td><td>✓</td><td>–</td></tr><tr><td><a href="#weblink">Weblink</a></td><td>Webadresse</td><td>✓</td><td>–</td></tr><tr><td><a href="#unterschrift">Unterschrift</a></td><td>Handschriftliche Unterschrift</td><td>✓</td><td>–</td></tr><tr><td><a href="#benutzer">Benutzer</a></td><td>Verweis auf eine Person</td><td>✓</td><td>–</td></tr><tr><td><a href="#erstellt-von">Erstellt von</a></td><td>Urheber des Eintrags</td><td>schreibgeschützt</td><td>–</td></tr><tr><td><a href="#erstellt-am">Erstellt am</a></td><td>Zeitpunkt der Anlage</td><td>schreibgeschützt</td><td>–</td></tr><tr><td><a href="#wert-uebernehmen">Wert übernehmen</a></td><td>Wert aus verknüpftem Eintrag</td><td>schreibgeschützt</td><td>–</td></tr><tr><td><a href="#summe-berechnen">Summe berechnen</a></td><td>Summe über verknüpfte Einträge</td><td>schreibgeschützt</td><td>–</td></tr><tr><td><a href="#formel">Formel</a></td><td>Berechneter Wert</td><td>schreibgeschützt</td><td>–</td></tr><tr><td><a href="#interne-verknuepfung">Interne Verknüpfung</a></td><td>Verweis auf Grid, Formular, Seite oder Link</td><td>✓</td><td>–</td></tr></tbody></table><hr><h2 id="textartige-typen" tabindex="-1">Textartige Typen <a class="header-anchor" href="#textartige-typen" aria-label="Permalink to &quot;Textartige Typen&quot;">​</a></h2><h3 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h3><p>Einzeiliger Text für Namen, Betreffzeilen, Kurzangaben.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Im Formular:</strong> einzeiliges Textfeld; über die Feldeinstellung <strong>Mehrzeilig</strong> auf mehrere Zeilen umstellbar</li><li><strong>Filter:</strong> entspricht, entspricht nicht, enthält, enthält nicht, ist leer, ist nicht leer</li></ul><h3 id="formatierter-text" tabindex="-1">Formatierter Text <a class="header-anchor" href="#formatierter-text" aria-label="Permalink to &quot;Formatierter Text&quot;">​</a></h3><p>Text mit Formatierungen wie Fettdruck, Listen und Überschriften.</p><ul><li><strong>Einstellungen:</strong> keine</li></ul><div class="warning custom-block"><p class="custom-block-title">Nicht in Formularen verfügbar</p><p>Für diesen Typ ist kein Formularfeld hinterlegt. Sollen Nutzer längeren Text erfassen, verwenden Sie <strong>Text</strong> mit der Feldeinstellung <em>Mehrzeilig</em>.</p></div><hr><h2 id="zahlen" tabindex="-1">Zahlen <a class="header-anchor" href="#zahlen" aria-label="Permalink to &quot;Zahlen&quot;">​</a></h2><h3 id="zahl" tabindex="-1">Zahl <a class="header-anchor" href="#zahl" aria-label="Permalink to &quot;Zahl&quot;">​</a></h3><p>Ganze Zahlen für Mengen, Anzahlen, Positionen.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Im Formular:</strong> Textfeld mit Zahlenprüfung</li><li><strong>Filter:</strong> entspricht, entspricht nicht, ist kleiner als, ist größer als, ist leer, ist nicht leer</li><li><strong>Summierbar</strong> in Gruppierungen und in der Summenzeile</li><li><strong>Fehlermeldung:</strong> <em>Es sind nur Zahlen (0-9) erlaubt</em></li></ul><h3 id="kommazahl" tabindex="-1">Kommazahl <a class="header-anchor" href="#kommazahl" aria-label="Permalink to &quot;Kommazahl&quot;">​</a></h3><p>Zahlen mit Nachkommastellen.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Filter:</strong> wie Zahl</li><li><strong>Summierbar</strong></li><li><strong>Fehlermeldung:</strong> <em>Es sind nur Gleitkommazahlen erlaubt</em></li></ul><h3 id="wahrung" tabindex="-1">Währung <a class="header-anchor" href="#wahrung" aria-label="Permalink to &quot;Währung&quot;">​</a></h3><p>Geldbeträge mit Währungsangabe und definierter Genauigkeit.</p><ul><li><strong>Einstellungen:</strong><ul><li><strong>Währung</strong> — Pflichtangabe, aus einer Liste</li><li><strong>Dezimalstellen</strong> — Standard <strong>2</strong></li></ul></li><li><strong>Darstellung:</strong> entsprechend der Spracheinstellung, also <code>1.234,56 €</code> im Deutschen</li><li><strong>Filter:</strong> wie Zahl</li><li><strong>Summierbar</strong></li></ul><div class="tip custom-block"><p class="custom-block-title">Dezimalstellen sind keine eigene Spalte</p><p>In der Oberfläche taucht <em>Dezimalstellen</em> als eigener Begriff auf. Es handelt sich dabei um die Einstellung dieses Typs, nicht um einen eigenständigen Spaltentyp.</p></div><hr><h2 id="datum-und-zeit" tabindex="-1">Datum und Zeit <a class="header-anchor" href="#datum-und-zeit" aria-label="Permalink to &quot;Datum und Zeit&quot;">​</a></h2><h3 id="datum" tabindex="-1">Datum <a class="header-anchor" href="#datum" aria-label="Permalink to &quot;Datum&quot;">​</a></h3><p>Ein Datum ohne Uhrzeit.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Filter:</strong> entspricht, entspricht nicht, ist vor, ist nach, ist leer, ist nicht leer</li><li><strong>Relative Angaben im Filter:</strong> heute, morgen, gestern, vor X Tagen, in X Tagen, exaktes Datum</li></ul><h3 id="datum-und-uhrzeit" tabindex="-1">Datum und Uhrzeit <a class="header-anchor" href="#datum-und-uhrzeit" aria-label="Permalink to &quot;Datum und Uhrzeit&quot;">​</a></h3><p>Ein genauer Zeitpunkt.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Filter:</strong> wie Datum</li><li><strong>Fehlermeldung:</strong> <em>Unerkanntes Datumsformat : {date}</em></li></ul><hr><h2 id="auswahl" tabindex="-1">Auswahl <a class="header-anchor" href="#auswahl" aria-label="Permalink to &quot;Auswahl&quot;">​</a></h2><h3 id="einzelauswahl" tabindex="-1">Einzelauswahl <a class="header-anchor" href="#einzelauswahl" aria-label="Permalink to &quot;Einzelauswahl&quot;">​</a></h3><p>Genau eine Option aus einer vorgegebenen Liste.</p><ul><li><strong>Einstellungen:</strong><ul><li><strong>Optionsliste</strong> — mindestens eine Option erforderlich</li><li><strong>Andere Eingaben zulassen</strong> — erlaubt zusätzlich Freitext</li></ul></li><li><strong>Im Formular:</strong> Komponententyp <em>Dropdown-Menü</em> oder <em>Liste</em></li><li><strong>Filter:</strong> entspricht, entspricht nicht, ist leer, ist nicht leer</li><li><strong>Fehlermeldungen:</strong> <em>Die Option darf nicht leer sein</em>, <em>Die Option darf kein Duplikat sein</em></li></ul><p>Dieser Typ ist Voraussetzung für den <a href="/seiten/auswertungen">Ringdiagramm-Block</a> und die übliche Grundlage für Kanban-Spalten.</p><h3 id="mehrfachauswahl" tabindex="-1">Mehrfachauswahl <a class="header-anchor" href="#mehrfachauswahl" aria-label="Permalink to &quot;Mehrfachauswahl&quot;">​</a></h3><p>Beliebig viele Optionen aus einer Liste.</p><ul><li><strong>Einstellungen:</strong> wie Einzelauswahl</li><li><strong>Im Formular:</strong> Komponententyp <em>Dropdown-Menü</em> oder <em>Liste</em>, mit Mehrfachauswahl</li><li><strong>Filter:</strong> zusätzlich <em>enthält eines von</em>, <em>enthält keines von</em>, <em>enthält alle von</em></li></ul><hr><h2 id="verknupfungen" tabindex="-1">Verknüpfungen <a class="header-anchor" href="#verknupfungen" aria-label="Permalink to &quot;Verknüpfungen&quot;">​</a></h2><h3 id="eintrag-verknupfen" tabindex="-1">Eintrag verknüpfen <a class="header-anchor" href="#eintrag-verknupfen" aria-label="Permalink to &quot;Eintrag verknüpfen&quot;">​</a></h3><p>Ein Verweis auf genau einen Eintrag in einem anderen Grid.</p><ul><li><strong>Einstellungen:</strong> Zielansicht auswählen (<em>Wählen Sie eine Grid-Ansicht, aus der Einträge verknüpft werden</em>)</li><li><strong>Im Formular:</strong> Auswahldialog über die Einträge des Zielgrids</li><li><strong>Filter:</strong> ist leer, ist nicht leer</li></ul><div class="warning custom-block"><p class="custom-block-title">Verschachtelte Verknüpfungen</p><p>ApptiveGrid meldet <em>Links auf Grids die bereits an einer anderen Stelle verlinkt wurden, sind noch nicht möglich.</em>. Sie können Verknüpfungen also nicht beliebig tief staffeln. Planen Sie Ihr Datenmodell entsprechend flach.</p></div><h3 id="mehrere-eintrage-verknupfen" tabindex="-1">Mehrere Einträge verknüpfen <a class="header-anchor" href="#mehrere-eintrage-verknupfen" aria-label="Permalink to &quot;Mehrere Einträge verknüpfen&quot;">​</a></h3><p>Verweise auf beliebig viele Einträge eines anderen Grids.</p><ul><li><strong>Einstellungen:</strong> wie oben</li><li><strong>Voraussetzung für:</strong> <a href="#summe-berechnen">Summe berechnen</a></li></ul><h3 id="interne-verknupfung" tabindex="-1">Interne Verknüpfung <a class="header-anchor" href="#interne-verknupfung" aria-label="Permalink to &quot;Interne Verknüpfung&quot;">​</a></h3><p>Ein Verweis auf ein Objekt innerhalb von ApptiveGrid.</p><ul><li><strong>Einstellungen:</strong> zulässige Zieltypen — <strong>Grid</strong>, <strong>Formular</strong>, <strong>Seite</strong>, <strong>Link</strong>. Standardmäßig sind alle vier erlaubt.</li><li><strong>Im Formular:</strong> Auswahlfeld für Ressourcen</li><li><strong>Filter:</strong> ist leer, ist nicht leer</li></ul><p>Nützlich, um aus einem Eintrag heraus direkt auf ein Formular oder ein Portal zu verweisen.</p><div class="tip custom-block"><p class="custom-block-title">Zieltyp „Link&quot; — als Button, mit Bezug zum Eintrag</p><p>Zeigt das Feld auf einen <strong>Link</strong> (den Freigabelink eines Formulars oder den Start-Link eines Flows), stellt ApptiveGrid den Wert als <strong>Button</strong> dar statt als Text. Ein Klick öffnet das Ziel in einem Overlay und übergibt dabei die <strong>URI und die ID des Eintrags</strong> als URL-Parameter — das Ziel weiß so, von welcher Zeile der Klick ausging.</p><p>Damit lassen sich aus einem Eintrag heraus Flows anstoßen, die auf genau diesen Eintrag wirken sollen — etwa ein Freigabeprozess oder eine Aktion, die den Datensatz aktualisiert.</p><p>→ <a href="/grids/flow-button">Flow per Button aus einem Eintrag starten</a></p></div><hr><h2 id="berechnete-felder" tabindex="-1">Berechnete Felder <a class="header-anchor" href="#berechnete-felder" aria-label="Permalink to &quot;Berechnete Felder&quot;">​</a></h2><p>Alle drei Typen sind <strong>schreibgeschützt</strong> und stehen <strong>nicht in Formularen</strong> zur Verfügung.</p><h3 id="wert-ubernehmen" tabindex="-1">Wert übernehmen <a class="header-anchor" href="#wert-ubernehmen" aria-label="Permalink to &quot;Wert übernehmen&quot;">​</a></h3><p>Holt einen Wert aus einem verknüpften Eintrag in das aktuelle Grid.</p><ul><li><strong>Einstellungen:</strong><ul><li><strong>Verknüpfungsfeld</strong> — welche Verknüpfungsspalte verwendet wird</li><li><strong>Zielfeld</strong> — welches Feld aus dem verknüpften Eintrag geholt wird</li></ul></li><li><strong>Voraussetzung:</strong> eine Spalte vom Typ <em>Eintrag verknüpfen</em></li></ul><div class="warning custom-block"><p class="custom-block-title">Nicht als Flow-Bedingung nutzbar</p><p>Dieser Typ kann im Flow-Trigger <em>Eintrag geändert</em> nicht als auslösendes Feld gewählt werden.</p></div><h3 id="summe-berechnen" tabindex="-1">Summe berechnen <a class="header-anchor" href="#summe-berechnen" aria-label="Permalink to &quot;Summe berechnen&quot;">​</a></h3><p>Summiert ein numerisches Feld über alle verknüpften Einträge.</p><ul><li><strong>Einstellungen:</strong><ul><li><strong>Verknüpfungsfeld</strong> — eine Spalte vom Typ <em>Mehrere Einträge verknüpfen</em></li><li><strong>Zielfeld</strong> — das zu summierende numerische Feld</li></ul></li><li><strong>Voraussetzung:</strong> eine Spalte vom Typ <em>Mehrere Einträge verknüpfen</em></li></ul><p>Typischer Fall: Ein Grid „Rechnungen&quot; summiert die Beträge aller verknüpften „Positionen&quot;.</p><h3 id="formel" tabindex="-1">Formel <a class="header-anchor" href="#formel" aria-label="Permalink to &quot;Formel&quot;">​</a></h3><p>Berechnet einen Wert aus einem Ausdruck.</p><ul><li><strong>Einstellungen:</strong><ul><li><strong>Ausdruck</strong> — in ApptiveScript, siehe <a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a></li><li><strong>Ergebnistyp</strong> — welchen Typ das Ergebnis hat</li></ul></li><li><strong>Editor:</strong> zeigt ein <em>Beispielergebnis</em> und den ermittelten Typ</li></ul><div class="warning custom-block"><p class="custom-block-title">Nicht als Flow-Bedingung nutzbar</p><p>Wie <em>Wert übernehmen</em> steht auch dieser Typ im Trigger <em>Eintrag geändert</em> nicht als auslösendes Feld zur Verfügung.</p></div><hr><h2 id="kontakt-und-ort" tabindex="-1">Kontakt und Ort <a class="header-anchor" href="#kontakt-und-ort" aria-label="Permalink to &quot;Kontakt und Ort&quot;">​</a></h2><h3 id="e-mail" tabindex="-1">E-Mail <a class="header-anchor" href="#e-mail" aria-label="Permalink to &quot;E-Mail&quot;">​</a></h3><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Fehlermeldung:</strong> <em>Gültige E-Mail-Adresse notwendig</em></li></ul><h3 id="telefon" tabindex="-1">Telefon <a class="header-anchor" href="#telefon" aria-label="Permalink to &quot;Telefon&quot;">​</a></h3><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Fehlermeldungen:</strong> <em>Bitte geben Sie eine gültige Telefonnummer ein</em>, <em>Internationale Vorwahl ist erforderlich (z.B. +49)</em></li></ul><div class="tip custom-block"><p class="custom-block-title">Internationale Vorwahl</p><p>Telefonnummern benötigen eine Ländervorwahl. Weisen Sie in Formularen mit einer Feldbeschreibung darauf hin, sonst häufen sich Fehleingaben.</p></div><h3 id="weblink" tabindex="-1">Weblink <a class="header-anchor" href="#weblink" aria-label="Permalink to &quot;Weblink&quot;">​</a></h3><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Fehlermeldung:</strong> <em>Bitte geben Sie eine gültige URL ein</em></li></ul><h3 id="adresse" tabindex="-1">Adresse <a class="header-anchor" href="#adresse" aria-label="Permalink to &quot;Adresse&quot;">​</a></h3><p>Eine strukturierte Postanschrift aus Land, Adresszeile 1 und 2, Ort und weiteren Teilfeldern. Enthält zusätzlich Koordinaten.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Fehlermeldung:</strong> <em>Bitte füllen Sie die erforderlichen Unterfelder aus</em></li></ul><div class="tip custom-block"><p class="custom-block-title">Geokodierung ist tarifabhängig</p><p>Das automatische Ermitteln von Koordinaten aus einer Adresse — und damit die Anzeige als Kartenmarkierung — steht nur im höchsten Tarif zur Verfügung.</p></div><h3 id="geolokalisierung" tabindex="-1">Geolokalisierung <a class="header-anchor" href="#geolokalisierung" aria-label="Permalink to &quot;Geolokalisierung&quot;">​</a></h3><p>Ein Koordinatenpaar.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Eingabeformat:</strong> <code>Breitengrad,Längengrad</code></li><li><strong>Fehlermeldung:</strong> <em>Muss das Format Latitude, Longitude haben (z.B. 50.12,6.543)</em></li></ul><hr><h2 id="dateien-und-unterschrift" tabindex="-1">Dateien und Unterschrift <a class="header-anchor" href="#dateien-und-unterschrift" aria-label="Permalink to &quot;Dateien und Unterschrift&quot;">​</a></h2><h3 id="dateien" tabindex="-1">Dateien <a class="header-anchor" href="#dateien" aria-label="Permalink to &quot;Dateien&quot;">​</a></h3><p>Beliebig viele Datei- und Bildanhänge.</p><ul><li><strong>Einstellungen:</strong> keine am Feld selbst</li><li><strong>Im Formular:</strong> Komponententyp <em>Datei auswählen</em>; optional <strong>Nur Hinzufügen von Dateien erlauben</strong>, sodass bestehende Anhänge nicht gelöscht werden können</li><li><strong>Grenze:</strong> die maximale Dateigröße ist tarifabhängig</li></ul><h3 id="unterschrift" tabindex="-1">Unterschrift <a class="header-anchor" href="#unterschrift" aria-label="Permalink to &quot;Unterschrift&quot;">​</a></h3><p>Eine mit Maus oder Finger gezeichnete Unterschrift.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Im Formular:</strong> Zeichenfläche mit dem Hinweis <em>Hier tippen zum Unterschreiben</em></li></ul><hr><h2 id="personenbezogene-typen" tabindex="-1">Personenbezogene Typen <a class="header-anchor" href="#personenbezogene-typen" aria-label="Permalink to &quot;Personenbezogene Typen&quot;">​</a></h2><h3 id="benutzer" tabindex="-1">Benutzer <a class="header-anchor" href="#benutzer" aria-label="Permalink to &quot;Benutzer&quot;">​</a></h3><p>Ein Verweis auf eine Person.</p><ul><li><strong>Einstellungen:</strong> keine</li><li><strong>Filter:</strong> <em>ist</em>, <em>ist nicht</em>, dazu der Ausdruck <em>angemeldeter Benutzer</em></li></ul><h3 id="erstellt-von" tabindex="-1">Erstellt von <a class="header-anchor" href="#erstellt-von" aria-label="Permalink to &quot;Erstellt von&quot;">​</a></h3><p>Wer den Eintrag angelegt hat. Wird automatisch gesetzt und ist nicht änderbar.</p><p>Mögliche Werte sind neben Personen auch <strong>Formular-Link</strong> (der Eintrag kam über ein Formular) und <strong>API Zugangsdaten</strong> (der Eintrag kam über die Programmierschnittstelle).</p><ul><li><strong>Filter:</strong> <em>ist</em>, <em>ist nicht</em>, dazu <em>angemeldeter Benutzer</em></li></ul><h3 id="erstellt-am" tabindex="-1">Erstellt am <a class="header-anchor" href="#erstellt-am" aria-label="Permalink to &quot;Erstellt am&quot;">​</a></h3><p>Zeitpunkt der Anlage. Wird automatisch gesetzt und ist nicht änderbar.</p><ul><li><strong>Filter:</strong> wie <em>Datum und Uhrzeit</em></li></ul><div class="warning custom-block"><p class="custom-block-title">Nicht als Flow-Bedingung nutzbar</p><p>Auch dieser Typ steht im Trigger <em>Eintrag geändert</em> nicht als auslösendes Feld zur Verfügung — er ändert sich nach der Anlage ohnehin nicht.</p></div><hr><h2 id="verwandte-seiten" tabindex="-1">Verwandte Seiten <a class="header-anchor" href="#verwandte-seiten" aria-label="Permalink to &quot;Verwandte Seiten&quot;">​</a></h2><ul><li><a href="/grids/felder">Felder anlegen und ändern</a></li><li><a href="/grids/verknuepfungen">Grids verknüpfen</a></li><li><a href="/grids/berechnete-felder">Berechnete Felder</a></li><li><a href="/referenz/filterbedingungen">Filterbedingungen</a></li></ul>',111)])])}const c=t(a,[["render",l]]);export{m as __pageData,c as default};
